$filter='WAKE_INPUT|CONFIRMED_WAKE|REPLY_SCOPE|ASR_FINAL|NATIVE_INTENT|VOICE MODE|NATIVE_SERVICE|NATIVE_RETRY|VOICE_SESSION recovery|VOICE_SESSION consumer_exit|NATIVE_DIALOGUE|REPLY_PIPELINE|OPUS_STREAM|TTS_WSS|TTS_DIALOGUE_BUFFER|TTS_SEGMENT|TTS_SSE|TTS_SESSION|TTS_SPOOL|TTS_TERMINAL_DRAIN|TLS_BIO|TLS_EOF_SOCKET|TLS_IO|PARAFORMER (ready_ms|endpoint|stage=)|NATIVE_ASR stage=2|VVALIYUN stage=|PHOTO RAM|PHOTO complete|CAPTURE_RESULT|CAPTURE_END|K7CLOUD native|SESSION end'
function Show-Line([string]$Line) {
  if($Line -notmatch $filter){return}
  if($Line -match 'Authorization|Bearer |api_key|password|passwd|secret|token='){return}
  $clean=$Line -replace '\x1b\[[0-9;]*[A-Za-z]',''
  if($clean -match 'rc=-|result=-|TLS_EOF|TLS_BIO|terminal=0') {Write-Host $clean -ForegroundColor Red}
  elseif($clean -match 'ASR_FINAL|VOICE MODE|NATIVE_INTENT') {Write-Host $clean -ForegroundColor Cyan}
  elseif($clean -match 'TTS_SEGMENT|TTS_SESSION|TTS_SPOOL|TTS_TERMINAL|TTS_SSE') {Write-Host $clean -ForegroundColor Yellow}
  else {Write-Host $clean}
}
