    """Never emit argv/maps/fd text. Same-user visibility errors refuse deletion."""
    uid = os.getuid()
    holders, active, unreadable = set(), [], []
    relevant = {"apt", "apt-get", "dpkg", "pip", "pip3", "uv", "npm", "yarn",
                "pnpm", "ninja", "make", "cmake", "ccache", "cargo"}
    for proc in pathlib.Path("/proc").iterdir():
        if not proc.name.isdigit() or int(proc.name) == os.getpid():
            continue
        try:
            args = (proc / "cmdline").read_bytes().split(b"\0")
            comm = (proc / "comm").read_text().strip()
            names = {os.path.basename(os.fsdecode(x)) for x in args[:5]}
            if comm in relevant or names & relevant:
                active.append(int(proc.name))
            if proc.stat().st_uid != uid:
                continue
            for fd in (proc / "fd").iterdir():
                try:
                    p = os.readlink(fd)
                    if p == root or p.startswith(root + "/"):
                        holders.add(p)
                except FileNotFoundError:
                    pass
            for line in (proc / "maps").read_text().splitlines():
                fields = line.split(None, 5)
                if len(fields) == 6 and (fields[5] == root or fields[5].startswith(root + "/")):
                    holders.add(fields[5])
        except (FileNotFoundError, ProcessLookupError):
            pass
        except PermissionError:
            try:
                if proc.stat().st_uid == uid:
                    unreadable.append(int(proc.name))
            except (FileNotFoundError, ProcessLookupError):
                pass
    return {"holders": sorted(holders), "active": active, "unreadable_same_uid": unreadable}


