extern "C" int k7_kws_assets_acquire(const k7_kws_config *config) {
  if (!config || !config->sha256) return -EINVAL;
  if (claimed.test_and_set(std::memory_order_acquire)) return -EBUSY;
  const auto &a = config->assets;
  int result = verify(a.encoder, 16u * 1024 * 1024, *config);
