{"i":0,"status":"fulfilled","value":{"chunk_id":"6ab3b3","wall_time_seconds":0.3179266,"exit_code":0,"original_token_count":2069,"output":"#ifndef K7_AEC_H
#define K7_AEC_H
#include <stddef.h>
#include <stdint.h>
#ifdef __cplusplus
extern "C" {
#endif

/* Optional worker-only SpeexDSP AEC. Never run in a PIO/ISR callback.
 * Each context has one owner; callers serialize process/reset/stats/destroy.
 * This API does not establish acoustic alignment or estimate a missing delay.
 */
#define K7_AEC_SAMPLE_RATE 16000u
#define K7_AEC_FRAME_SAMPLES 320u
#define K7_AEC_DEFAULT_ARENA_BYTES (256u * 1024u)
enum k7_aec_flags {
  K7_AEC_ALIGNMENT_VERIFIED = 1u,
  K7_AEC_REFERENCE_VALID = 2u,
  K7_AEC_EXPLICIT_MUTED = 4u,
  K7_AEC_CANCELLED_TAIL = 8u
};
enum k7_aec_discontinuity {
  K7_AEC_GAP = 1, K7_AEC_CLOCK_CHANGE, K7_AEC_GENERATION_CHANGE,
  K7_AEC_CANCEL_TAIL, K7_AEC_BAD_REFERENCE, K7_AEC_LIBRARY_FAULT
};
struct k7_aec_config {
  uint32_t tail_samples; /* 0 = 1600 (100 ms); 320..5120, multiple of 320. */
  size_t arena_bytes;    /* 0 = 256 KiB; fixed allocation at create only. */
};
struct k7_aec_frame {
  const int16_t *mic;
  const int16_t *render; /* NULL only for explicit, independently proven mute. */
  uint64_t mic_first_sample;
  uint64_t render_first_sample; /* Both mapped to the SAME calibrated clock. */
  uint32_t clock_epoch;
  uint32_t render_generation;  /* 0 only for explicit mute. */
  uint32_t flags;
  uint16_t samples;            /* Exactly 320; no zero-padding partial input. */
};
struct k7_aec_stats {
  uint64_t frames, rejected, resets, warnings;
  uint64_t clipped_mic, clipped_render;
  size_t arena_used, arena_bytes, allocations;
  uint32_t ready, last_discontinuity;
};
struct k7_aec;
int k7_aec_create(const struct k7_aec_config *, struct k7_aec **out);
/* Explicit caller assertion after calibrated alignment, never just FIFO index
 * equality. Reset loses filter adaptation. No output until this succeeds. */
int k7_aec_align(struct k7_aec *, uint32_t clock_epoch,
                 uint32_t render_generation, uint64_t first_sample,
                 uint32_t flags);
/* On any failure output is untouched; caller must NOT label it cleaned audio.
 * Discontinuities latch not-ready until an explicit, verified align call. */
int k7_aec_process(struct k7_aec *, const struct k7_aec_frame *, int16_t out[320]);
int k7_aec_invalidate(struct k7_aec *, enum k7_aec_discontinuity);
int k7_aec_get_stats(struct k7_aec *, struct k7_aec_stats *);
int k7_aec_destroy(struct k7_aec *);
/* Optional normalized-float ingress: all finite/in-range before ANY write. */
int k7_aec_float_to_s16(const float *, size_t count, int16_t *out);

/* Diagnostic-only worker path for an UNVERIFIED timing hypothesis. These
 * residual samples MUST NOT enter KWS/ASR/control as "clean" audio.
 * Reset/process always leave stats.ready == 0; diagnostic processing never
 * increments verified stats.frames. All normal allocation guards still apply.
 * Never mix this path and verified process on one live context. Successful
 * align resets the filter and closes the probe; explicit invalidate also
 * closes it. All outputs are untouched on error. No NULL/synthetic mute. */
int k7_aec_diagnostic_reset(struct k7_aec *);
int k7_aec_diagnostic_process(struct k7_aec *, const int16_t *mic,
  const int16_t *reference, size_t samples, int16_t out[320]);

#ifdef __cplusplus
}
#endif
#endif
int k7_aec_invalidate(struct k7_aec *ctx, enum k7_aec_discontinuity reason)
{
  if (!ctx || reason < K7_AEC_GAP || reason > K7_AEC_LIBRARY_FAULT) return -EINVAL;
  ctx->stats.ready = 0; ctx->stats.last_discontinuity = (unsigned)reason;
  ctx->diagnostic_active = 0;
  return 0;
}
int k7_aec_get_stats(struct k7_aec *ctx, struct k7_aec_stats *out)
{
  if (!ctx || !out) return -EINVAL;
  *out = ctx->stats;
  return 0;
}
int k7_aec_destroy(struct k7_aec *ctx)
{
  if (!ctx) return 0;
  /* All upstream allocations live in this context's arena, including FFTs. */
  free(ctx->arena); free(ctx);
  return 0;
}
int k7_aec_float_to_s16(const float *input, size_t count, int16_t *out)
{
  size_t i;
  if (!input || !out || !count || count > 320u) return -EINVAL;
  for (i = 0; i < count; ++i)
    if (!isfinite(input[i]) || input[i] < -1.0f || input[i] > 1.0f) return -ERANGE;
  for (i = 0; i < count; ++i)
    out[i] = input[i] == -1.0f ? INT16_MIN : (int16_t)(input[i] * 32767.0f);
  return 0;
}

int k7_aec_diagnostic_reset(struct k7_aec *ctx)
{
  if (!ctx) return -EINVAL;
  ctx->stats.ready = 0;
  ctx->diagnostic_active = 0;
  if (enter(ctx)) return -EBUSY;
  if (setjmp(ctx->unwind)) {
    leave(); return invalidate(ctx, K7_AEC_LIBRARY_FAULT, ctx->fault);
  }
  speex_echo_state_reset(ctx->state);
  ctx->diagnostic_active = 1;
  leave();
  return 0;
}

int k7_aec_diagnostic_process(struct k7_aec *ctx, const int16_t *mic,
  const int16_t *reference, size_t samples, int16_t out[320])
{
  int16_t result[320];
  uint64_t warnings;
  if (!ctx) return -EINVAL;
  ctx->stats.ready = 0;
  if (!mic || !reference || !out || samples != 320)
    return invalidate(ctx, K7_AEC_BAD_REFERENCE, -EINVAL);
  if (!ctx->diagnostic_active) return -EPIPE;
  if (enter(ctx)) return -EBUSY;
  if (setjmp(ctx->unwind)) {
    leave(); return invalidate(ctx, K7_AEC_LIBRARY_FAULT, ctx->fault);
  }
  warnings = ctx->stats.warnings;
  speex_echo_cancellation(ctx->state, mic, reference, result);
  if (ctx->stats.warnings != warnings) {
    leave(); return invalidate(ctx, K7_AEC_LIBRARY_FAULT, -EIO);
  }
  memcpy(out, result, sizeof(result));
  leave();
  return 0;
}
#ifndef VV_CANCEL_TAIL_H
#define VV_CANCEL_TAIL_H
#include "vv_barge_input.h"
#ifdef __cplusplus
extern "C" {
#endif
#define VV_CANCEL_TAIL_FRAMES 64u
#define VV_CANCEL_TAIL_WAIT_MS 1500u
struct vv_cancel_tail;
struct vv_cancel_tail_transform {
  void *arg;
  /* Actual worker monotonic clock, checked before and after transformation.
   * UINT64_MAX/rollback/expired budget abort; this grants no audio authority. */
  uint64_t (*now_ms)(void *);
  /* Independent, qualified worker transform, absent by default. Input is RAW
   * and may contain unknown amplifier/codec/acoustic tail. This callback must
   * NEVER return raw input as clean merely because TX retired or time passed.
   * Return 0 only for the same exact physical range with independently valid
   * calibration/near-end preservation; -EAGAIN while unknown, other <0 abort.
   * Existing barge authority revalidates this range before queue acceptance.
   * Bounded and non-reentrant: may not destroy/reset this buffer or queue;
   * its qualification dependencies must stay pinned through the callback.
   * No production transform/qualified registry is provided by this draft. */
  int (*frame)(void *,const struct vv_barge_ticket *,const struct k7_voice_frame *,
               struct k7_voice_frame *,enum vv_barge_material *);
};
/* Single serialized worker only (not PIO/KWS callback). The manager's single
 * RX consumer must copy frames into a nonblocking upstream queue; it must not
 * wait for this transform. Caller retains q and joins workers before destroy.
 * 64 complete raw frames are bounded staging, never an ASR input API. */
int vv_cancel_tail_create(struct vv_barge_input *q,const struct vv_barge_ticket *,
                          uint64_t now_ms,struct vv_cancel_tail **);
int vv_cancel_tail_append(struct vv_cancel_tail *,const struct vv_confirmed_wake_context *,
                          const struct k7_voice_frame *,uint64_t now_ms);
/* At most one frame per call. 1 forwarded, 0 no pending frame, -EAGAIN waiting
 * for independent qualification. Unknown data is retained and never padded. */
int vv_cancel_tail_forward(struct vv_cancel_tail *,const struct vv_cancel_tail_transform *,uint64_t now_ms);
/* Serial worker hands over at an empty boundary only. Future frames must use
 * the SAME qualified lineage and exact next physical index through existing
 * barge frame ingress. This lifts a staging barrier, not acoustic authority. */
int vv_cancel_tail_finish(struct vv_cancel_tail *,uint64_t now_ms,uint64_t *first,uint64_t *next);
void vv_cancel_tail_destroy(struct vv_cancel_tail *);
size_t vv_cancel_tail_storage_bytes(void);
#ifdef __cplusplus
}
#endif
#endif
"}}

