static ssize_t body_read(void *arg,size_t offset,void *dst,size_t capacity) {
  struct body *b=arg;
  if(offset>b->length) return -1;
  size_t n=b->length-offset; if(n>capacity) n=capacity;
  memcpy(dst,b->text+offset,n); return (ssize_t)n;
